head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====
// 확인 대상 컬럼 : 연도(yearSuffix) / 월(monthNames) / 일(dateSuffix) / 오전오후(ampm)
scwin.COLS = [["year", "연도(yearSuffix=Year)"], ["month", "월(monthNames=Jan~Dec)"],
    ["date", "일(dateSuffix=Day)"], ["ampm", "오전오후(ampm=AM,PM)"]];

// 컬럼에 실제로 표시된 라벨 텍스트를 읽어 출력
scwin.btn_getLabel_onclick = function (e) {
    var objComp = $p.getComponentById("target1");

    for (var i = 0; i < scwin.COLS.length; i++) {
        var strType = scwin.COLS[i][0];
        var strName = scwin.COLS[i][1];

        if (!objComp.colTypeObj || !objComp.colTypeObj.hasOwnProperty(strType)) {
            scwin.setReturnValue("[" + strName + " 컬럼] 컬럼이 존재하지 않음");
            continue;
        }

        var objCol = objComp.childControlList[objComp.colTypeObj[strType]];
        var objBox = objCol && objCol.dom && objCol.dom.itembox;
        var arrText = [];

        if (objBox) {
            var arrNode = objBox.childNodes;
            for (var j = 0; j < arrNode.length; j++) {
                var strText = (arrNode[j].textContent || "").trim();
                if (strText) {
                    arrText.push(strText);
                }
            }
        }

        if (arrText.length === 0) {
            scwin.setReturnValue("[" + strName + " 컬럼 표시 라벨] 없음");
        } else if (arrText.length <= 12) {
            scwin.setReturnValue("[" + strName + " 컬럼 표시 라벨] [" + arrText.join(", ") + "]");
        } else {
            scwin.setReturnValue("[" + strName + " 컬럼 표시 라벨] 첫번째 '" + arrText[0]
                + "' / 마지막 '" + arrText[arrText.length - 1] + "'");
        }
    }
};
